#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <vector>
using namespace std;

vector<int> c0(1, 0), c1(1, 0);

void insertValue(long long x) {
    int v = 0;
    for (int b = 29; b >= 0; b--) {
        vector<int>& next = ((x >> b) & 1) ? c1 : c0;
        if (!next[v]) {
            c0.push_back(0);
            c1.push_back(0);
            next[v] = (int)c0.size() - 1;
        }
        v = next[v];
    }
}

long long queryValue(long long y) {
    int v = 0;
    long long res = 0;
    for (int b = 29; b >= 0; b--) {
        int want, other;
        if ((y >> b) & 1) {
            want = c0[v];
            other = c1[v];
        } else {
            want = c1[v];
            other = c0[v];
        }
        if (want) {
            res |= 1LL << b;
            v = want;
        } else {
            v = other;
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long L;
    cin >> n >> L;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    vector<long long> prefix(n + 1, 0);
    for (long long i = 0; i < n; i++) prefix[i + 1] = prefix[i] ^ a[i];
    long long best = 0;
    for (long long i = L; i <= n; i++) {
        insertValue(prefix[i - L]);
        best = max(best, queryValue(prefix[i]));
    }
    cout << best << "\n";

    return 0;
}

