import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] c0, c1;
    static int nodes;

    static void insertValue(long x) {
        int v = 0;
        for (int b = 29; b >= 0; b--) {
            if (((x >> b) & 1L) != 0) {
                if (c1[v] == 0) c1[v] = ++nodes;
                v = c1[v];
            } else {
                if (c0[v] == 0) c0[v] = ++nodes;
                v = c0[v];
            }
        }
    }

    static long queryValue(long y) {
        int v = 0;
        long res = 0;
        for (int b = 29; b >= 0; b--) {
            int want, other;
            if (((y >> b) & 1L) != 0) {
                want = c0[v];
                other = c1[v];
            } else {
                want = c1[v];
                other = c0[v];
            }
            if (want != 0) {
                res |= 1L << b;
                v = want;
            } else {
                v = other;
            }
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long L = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int cn = (int) n, cl = (int) L;
        long[] prefix = new long[cn + 1];
        for (int i = 0; i < cn; i++) prefix[i + 1] = prefix[i] ^ a[i];
        c0 = new int[30 * (cn + 1) + 5];
        c1 = new int[30 * (cn + 1) + 5];
        nodes = 0;
        long best = 0;
        for (int i = cl; i <= cn; i++) {
            insertValue(prefix[i - cl]);
            best = Math.max(best, queryValue(prefix[i]));
        }
        System.out.println(best);
    }
}
